// Obtener el teléfono del webhook
const tel = $('Webhook').first().json.body.tel;

// Obtener todos los mensajes de Twilio
const messages = $input.all()[0].json.messages;

// Normalizar el número de teléfono para la búsqueda
// Asegurarse de que tenga el formato correcto con '+'
const normalizedTel = tel.startsWith('+') ? tel : `+${tel}`;

// Buscar mensajes enviados desde el número específico
const sentMessages = messages.filter(msg => 
  msg.to === `whatsapp:${normalizedTel}` && 
  msg.direction === 'outbound-api'
);

// Función para extraer datos del mensaje de recordatorio
function extractAppointmentData(messageBody) {
  const asesorMatch = messageBody.match(/Asesor asignado:\s*(.+)/);
  const dominioMatch = messageBody.match(/Dominio:\s*(.+)/);
  const diaMatch = messageBody.match(/Día:\s*(.+)/);
  const horaMatch = messageBody.match(/Hora de atención:\s*(.+)/);

  return {
    asesor: asesorMatch ? asesorMatch[1].trim() : null,
    dominio: dominioMatch ? dominioMatch[1].trim() : null,
    fecha: diaMatch ? diaMatch[1].trim() : null,
    hora: horaMatch ? horaMatch[1].trim() : null
  };
}

// Buscar el mensaje que contiene "Nos comunicamos de CENTRO AUTOMOTORES"
const appointmentMessage = sentMessages.find(msg => 
  msg.body && msg.body.includes('Nos comunicamos de CENTRO AUTOMOTORES')
);

if (appointmentMessage) {
  const data = extractAppointmentData(appointmentMessage.body);

  return [{
    json: {
      mensaje_encontrado: true,
      fecha: data.fecha,
      hora: data.hora,
      dominio: data.dominio,
      asesor_asignado: data.asesor,
      mensaje_completo: appointmentMessage.body,
      fecha_envio_mensaje: appointmentMessage.date_sent,
      sid: appointmentMessage.sid
    }
  }];
} else {
  return [{
    json: {
      mensaje_encontrado: false,
      fecha: null,
      hora: null,
      dominio: null,
      asesor_asignado: null,
      error: 'No se encontró el mensaje de recordatorio de turno',
      telefono_buscado: `whatsapp:${normalizedTel}`,
      mensajes_encontrados: sentMessages.length,
      debug_info: {
        tel_original: tel,
        tel_normalizado: normalizedTel,
        mensajes_totales: messages.length
      }
    }
  }];
}

